#include "Halide.h"

// include common definitions (DATA_TYPE, N, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (for N, etc.)
#include "durbin.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Initialize r[i] = n + 1 - i
static void init_array(int n, Halide::Buffer<num_t, 1> r) {
    Var i("i");
    Func init_r("init_r");

    // r[i] = n + 1 - i
    init_r(i) = cast<num_t>(n + 1 - i);

    init_r.realize(r);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers corresponding to C arrays r[N], y[N]
    Halide::Buffer<num_t, 1> r(n);
    Halide::Buffer<num_t, 1> y_curr(n);
    Halide::Buffer<num_t, 1> y_next(n);

    // Initialize r
    init_array(n, r);

    // Halide pipeline for a single Durbin iteration step: given the current
    // y (y_curr), k, and alpha, compute the updated y (y_next).
    //
    // This corresponds to:
    //
    // for (i = 0; i < k; i++)
    //     z[i] = y[i] + alpha * y[k - i - 1];
    // for (i = 0; i < k; i++)
    //     y[i] = z[i];
    // y[k] = alpha;
    //
    // which can be combined into:
    //
    // for (i = 0; i < k; i++) y_new[i] = y[i] + alpha * y[k - i - 1];
    // y_new[k] = alpha;
    // for (i > k) y_new[i] = y[i];  (not used later, but we keep it)
    //
    ImageParam y_param(type_of<num_t>(), 1, "y_param");
    Param<num_t> alpha_param("alpha_param");
    Param<int> k_param("k_param");

    Var i("i");

    // Wrap y_param in a Func so we can apply a boundary condition
    Func y_base("y_base");
    y_base(i) = y_param(i);

    // Extend y with a constant exterior value (0) so that accessing
    // y(k - i - 1) for i >= k is still defined (though these values
    // are ignored logically by the select below).
    Func y_ext = BoundaryConditions::constant_exterior(y_base, cast<num_t>(0));

    // Compute updated y
    Func update_y("update_y");
    Expr val = select(
        i < k_param,
        // For i < k: y_new[i] = y[i] + alpha * y[k - i - 1]
        y_param(i) + alpha_param * y_ext(k_param - i - 1),
        select(
            // For i == k: y_new[k] = alpha
            i == k_param,
            alpha_param,
            // For i > k: leave y unchanged
            y_param(i)));

    update_y(i) = val;

    // JIT-compile the per-iteration update pipeline once
    update_y.compile_jit();

    // Initial conditions from the original C kernel:
    //
    // y[0] = -r[0];
    // beta = 1.0;
    // alpha = -r[0];
    num_t alpha = -r(0);
    num_t beta = static_cast<num_t>(1.0);

    // Initialize y_curr; only y_curr(0) is defined by the algorithm
    for (int idx = 0; idx < n; ++idx) {
        y_curr(idx) = static_cast<num_t>(0.0);
        y_next(idx) = static_cast<num_t>(0.0);
    }
    y_curr(0) = -r(0);

    using clock = std::chrono::high_resolution_clock;
    auto start = clock::now();

    // Main Durbin iteration:
    //
    // for (k = 1; k < n; k++) {
    //   beta = (1 - alpha*alpha) * beta;
    //   sum = 0;
    //   for (i = 0; i < k; i++) sum += r[k - i - 1] * y[i];
    //   alpha = -(r[k] + sum) / beta;
    //   update y as described above
    // }
    //
    for (int k = 1; k < n; ++k) {
        beta = (static_cast<num_t>(1.0) - alpha * alpha) * beta;

        num_t sum = static_cast<num_t>(0.0);
        for (int i_host = 0; i_host < k; ++i_host) {
            sum += r(k - i_host - 1) * y_curr(i_host);
        }

        alpha = -(r(k) + sum) / beta;

        // Bind current y and parameters, then realize updated y into y_next
        y_param.set(y_curr);
        alpha_param.set(alpha);
        k_param.set(k);

        update_y.realize(y_next);

        // Swap current and next buffers
        std::swap(y_curr, y_next);
    }

    auto end = clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result vector y
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i_idx = 0; i_idx < n; ++i_idx) {
            std::cerr << y_curr(i_idx) << '\n';
        }
    }

    // Print elapsed time in seconds
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
