void init_array(int n,
                Halide::Buffer<num_t, 1> r) {
    Var i("i");
    Func init_r("init_r");

    // r[i] = n + 1 - i
    init_r(i) = cast<num_t>(n + 1 - i);

    init_r.realize(r);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers corresponding to r[N] and y[N]
    Halide::Buffer<num_t, 1> r(n);
    Halide::Buffer<num_t, 1> y_curr(n);
    Halide::Buffer<num_t, 1> y_next(n);

    // Initialize r
    init_array(n, r);

    // ------------------------------------------------------------------
    // Build Halide pipelines for the inner computations of the Durbin kernel
    // ------------------------------------------------------------------

    // ImageParams for r and y
    ImageParam r_param(type_of<num_t>(), 1, "r_param");
    ImageParam y_param(type_of<num_t>(), 1, "y_param");

    // Parameters for the current iteration index k and scalar alpha
    Param<int>    k_param("k");
    Param<num_t>  alpha_param("alpha");

    // Func to compute:
    //   sum = sum_{i=0..k-1} r[k - i - 1] * y[i]
    Func dot("dot");
    {
        RDom ri(0, k_param, "ri");
        dot() = cast<num_t>(0);
        dot() += r_param(k_param - ri - 1) * y_param(ri);
    }

    // Func to compute updated y for a given k, alpha, and previous y:
    //
    // For i < k:  y_new[i] = y[i] + alpha * y[k - i - 1]
    // For i == k: y_new[k] = alpha
    // For i > k:  y_new[i] = y[i]   (unchanged, as in the original code)
    Func y_update("y_update");
    {
        Var i("i");
        y_update(i) =
            select(i < k_param,
                   y_param(i) + alpha_param * y_param(k_param - i - 1),
                   select(i == k_param,
                          alpha_param,
                          y_param(i)));
    }

    // r is constant throughout; bind it once
    r_param.set(r);

    // JIT-compile the Halide pipelines ahead of timing
    dot.compile_jit();
    y_update.compile_jit();

    // ------------------------------------------------------------------
    // Durbin kernel (host-controlled loop over k)
    // ------------------------------------------------------------------

    // Initial conditions:
    // y[0] = -r[0];
    // beta = 1.0;
    // alpha = -r[0];
    num_t beta  = static_cast<num_t>(1.0);
    num_t alpha = -r(0);

    y_curr(0) = -r(0);
    // The remaining entries are not used before being written,
    // but we can initialize them to zero for completeness.
    for (int i = 1; i < n; i++) {
        y_curr(i) = static_cast<num_t>(0);
        y_next(i) = static_cast<num_t>(0);
    }

    using clock = std::chrono::high_resolution_clock;
    auto start = clock::now();

    for (int k = 1; k < n; k++) {
        // beta = (1 - alpha*alpha) * beta;
        beta = (static_cast<num_t>(1.0) - alpha * alpha) * beta;

        // sum = sum_{i=0..k-1} r[k-i-1] * y[i];
        k_param.set(k);
        y_param.set(y_curr);
        Halide::Buffer<num_t> sum_buf = dot.realize();
        num_t sum = sum_buf();

        // alpha = -(r[k] + sum) / beta;
        alpha = -(r(k) + sum) / beta;
        alpha_param.set(alpha);

        // Compute updated y into y_next
        y_param.set(y_curr);
        y_update.realize(y_next);

        // Prepare for next iteration: new y becomes current y
        std::swap(y_curr, y_next);
    }

    auto end = clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // ------------------------------------------------------------------
    // Print results (to prevent dead-code elimination and for checking)
    // ------------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            std::cerr << y_curr(i) << '\n';
        }
    }

    // Print timing in seconds
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
