// include common definitions (DATA_TYPE, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (N, etc.)
#include "durbin.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize the input array r:
 *   for (i = 0; i < n; i++)
 *       r[i] = n + 1 - i;
 *
 * Implemented with a simple Halide Func for consistency with the example.
 */
static void init_array(int n, Halide::Buffer<num_t> r) {
    Var i("i");
    Func init_r("init_r");

    // r[i] = n + 1 - i;
    init_r(i) = cast<num_t>(n + 1 - i);

    // Realize into the provided buffer.
    init_r.realize(r);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers:
    // r: input array, length n
    // y_curr: current solution vector y
    // y_next: scratch buffer used for the next y
    Buffer<num_t> r(n);
    Buffer<num_t> y_curr(n);
    Buffer<num_t> y_next(n);

    // Initialize r
    init_array(n, r);

    // Initialize y to 0, then set y[0] = -r[0] as in the original code.
    for (int i = 0; i < n; i++) {
        y_curr(i) = (num_t)0;
    }
    y_curr(0) = -r(0);

    // Scalars alpha, beta, sum as in the C code.
    num_t alpha = -r(0);
    num_t beta  = (num_t)1.0;

    // --------------------------------------------------------------------
    // Halide setup for the per-iteration work (the kernel_durbin loop body).
    // We follow rule 5: host-driven iteration over k, and use Halide for
    // the inner computations that are parallel in i.
    // --------------------------------------------------------------------

    // ImageParams for r and the current y.
    ImageParam r_param(type_of<num_t>(), 1, "r_param");
    ImageParam y_param(type_of<num_t>(), 1, "y_param");

    // Params for the current iteration index k and the scalar alpha.
    Param<int>   k_param("k");
    Param<num_t> alpha_param("alpha");

    // We will clamp accesses to y to avoid any out-of-bounds generated
    // by index expressions like (k - i - 1). This satisfies Halide's
    // bounds inference requirements (see rule 7).
    Func y_bounded("y_bounded");
    y_bounded = Halide::BoundaryConditions::repeat_edge(y_param);

    // --------------------------------------------------------------------
    // 1) Halide Func to compute:
    //    sum = sum_{i=0}^{k-1} r[k-i-1] * y[i]
    // --------------------------------------------------------------------
    Func sum_f("sum");
    RDom ri(0, k_param, "ri");

    sum_f() = cast<num_t>(0);
    sum_f() += r_param(k_param - ri - 1) * y_bounded(ri);

    // --------------------------------------------------------------------
    // 2) Halide Func to compute the updated y vector:
    //
    //    For 0 <= i < k:    y_new[i] = y[i] + alpha * y[k-i-1];
    //    For i == k:        y_new[k] = alpha;
    //    For i > k:         y_new[i] = y[i]; (carry forward)
    //
    // We implement this for all i in [0, n-1] and use a select to choose
    // the appropriate expression. y_bounded ensures all accesses are in-bounds.
    // --------------------------------------------------------------------
    Var i("i");
    Func y_update("y_update");

    Expr idx     = i;
    Expr base    = y_bounded(idx);
    Expr mirror  = y_bounded(k_param - idx - 1);
    Expr updated = base + alpha_param * mirror;

    y_update(i) =
        select(idx <  k_param, updated,
               select(idx == k_param, alpha_param,
                      base));

    // Tie r_param to the input buffer once; y_param will be rebound each
    // iteration to the current y buffer.
    r_param.set(r);

    // Compile the Halide pipelines ahead of timing so we don't include
    // JIT compile time in the measurement.
    sum_f.compile_jit();
    y_update.compile_jit();

    // --------------------------------------------------------------------
    // Run the Durbin iteration in C++, using Halide for the per-k work.
    // --------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int k = 1; k < n; k++) {
        // beta = (1 - alpha * alpha) * beta;
        beta = (num_t(1.0) - alpha * alpha) * beta;

        // Bind current k and y to the Halide Parameters.
        k_param.set(k);
        y_param.set(y_curr);

        // Compute "sum" using the Halide reduction sum_f.
        Realization sum_real = sum_f.realize();
        Buffer<num_t> sum_buf = sum_real[0];
        num_t sum = sum_buf();

        // alpha = - (r[k] + sum) / beta;
        alpha = -(r(k) + sum) / beta;
        alpha_param.set(alpha);

        // Compute the updated y into y_next.
        y_update.realize(y_next);

        // Swap buffers so that y_curr always holds the latest state.
        y_curr.swap(y_next);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // --------------------------------------------------------------------
    // Print results (mainly to prevent dead-code elimination), matching
    // the style from the example.
    // --------------------------------------------------------------------
    using namespace std::string_literals;

    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            std::cerr << y_curr(i) << '\n';
        }
    }

    // Print timing in seconds with 6 decimal places.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
