#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>
#include <algorithm>

#include "Halide.h"

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "durbin.hpp"

using num_t = DATA_TYPE;

using namespace Halide;


/* Array initialization: r[i] = n + 1 - i */
static
void init_array(int n,
                Halide::Buffer<num_t, 1> r) {
    Var i("i");
    Func init_r("init_r");

    // r[i] = (n + 1 - i)
    Expr N_expr = cast<int>(n);
    init_r(i) = cast<num_t>(N_expr + 1 - i);

    init_r.realize(r);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers corresponding to:
    //   r[0..n-1]
    //   y[0..n-1]  (current solution)
    //   y_new[0..n-1] (next solution, for double buffering)
    Buffer<num_t, 1> r(n);
    Buffer<num_t, 1> y(n);
    Buffer<num_t, 1> y_new(n);

    // Initialize r
    init_array(n, r);

    // Initialize y, y_new to 0 (only y[0] is immediately overwritten)
    {
        Var i("i");
        Func init_y("init_y");
        init_y(i) = cast<num_t>(0);
        init_y.realize(y);
        init_y.realize(y_new);
    }

    // Set up Halide parameters and Funcs that implement the per-iteration
    // vector operations of the Durbin algorithm.

    // r and y are inputs to the Halide pipelines
    ImageParam r_param(type_of<num_t>(), 1, "r_param");
    ImageParam y_param(type_of<num_t>(), 1, "y_param");

    // Current iteration index k and scalar alpha are runtime parameters
    Param<int>   k_param("k");
    Param<num_t> alpha_param("alpha_param");

    // Reduction to compute:
    //   sum = sum_{i=0..k-1} r[k-i-1] * y[i]
    Func sum_f("sum_f");
    {
        RDom r_sum(0, k_param, "r_sum");
        sum_f() = cast<num_t>(0);
        sum_f() += r_param(k_param - r_sum - 1) * y_param(r_sum);
    }

    // Compute the next y[0..k] from the current y[0..k-1] and alpha:
    //
    //   For i in [0, k-1]:
    //     y_next[i] = y[i] + alpha * y[k-i-1]
    //   y_next[k] = alpha
    //
    // We implement this as:
    //   pure definition: y_next(i) = alpha (for all i)
    //   update over i in [0, k-1]: y_next(i) = y[i] + alpha * y[k-i-1]
    Func y_next("y_next");
    {
        Var i("i");
        y_next(i) = alpha_param;  // default value; will remain at i == k

        RDom r_upd(0, k_param, "r_upd");
        y_next(r_upd) = y_param(r_upd) +
                        alpha_param * y_param(k_param - r_upd - 1);
    }

    // Bind the time-invariant input r
    r_param.set(r);

    // JIT-compile the Halide pipelines once
    sum_f.compile_jit();
    y_next.compile_jit();

    // Durbin scalar state
    num_t alpha;
    num_t beta;

    // Initial conditions:
    //   y[0] = -r[0];
    //   beta = 1.0;
    //   alpha = -r[0];
    y(0) = -r(0);
    alpha = -r(0);
    beta  = (num_t)1.0;

    // Buffer to hold the scalar reduction result sum_f()
    Buffer<num_t> sum_buf;  // 0-D buffer

    // Start timer for the main kernel
    auto start = std::chrono::high_resolution_clock::now();

    // Main Durbin loop:
    // for (k = 1; k < n; k++) {
    //   beta = (1 - alpha*alpha)*beta;
    //   sum  = sum_{i=0..k-1} r[k-i-1]*y[i];
    //   alpha = -(r[k] + sum) / beta;
    //   update y[0..k] as above;
    // }
    for (int k = 1; k < n; k++) {
        // Update beta
        beta = ((num_t)1.0 - alpha * alpha) * beta;

        // Bind current k and y to the Halide pipelines
        k_param.set(k);
        y_param.set(y);

        // Compute sum = sum_{i=0..k-1} r[k-i-1] * y[i]
        sum_f.realize(sum_buf);
        num_t sum = sum_buf();

        // Update alpha
        alpha = -(r(k) + sum) / beta;

        // Compute y_next[0..k] with the new alpha
        alpha_param.set(alpha);

        // Realize y_next into the first (k+1) elements of y_new,
        // using a cropped view so we avoid copying.
        Buffer<num_t, 1> y_slice = y_new.cropped(0, 0, k + 1);
        y_next.realize(y_slice);

        // Swap current and next y buffers
        std::swap(y, y_new);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (optional, mainly for debugging/correctness checking)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            std::cerr << y(i) << '\n';
        }
    }

    // Print timing (seconds) to stdout
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
